// count.c: log every open()
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdio.h>
int open(const char *p, int f, ...) {
    static int (*real)(const char*, int, ...);
    if (!real) real = dlsym(RTLD_NEXT, "open");
    fprintf(stderr, "open(%s)\n", p);
    return real(p, f, 0644);
}
